import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  random,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// Portuguese Word Bank
const WORD_BANK = [
  "Saudade", "Fado", "Amor", "Café", "Praia", "Lisboa", "Porto", "Vida", 
  "Sol", "Mar", "Alegria", "Festa", "Família", "Amigo", "Obrigado", 
  "Olá", "Sim", "Não", "Casa", "Tempo", "Coração", "Sonho", "Luz", 
  "Paz", "Esperança", "Liberdade", "Beleza", "Coragem", "Felicidade", 
  "Paixão", "Natureza", "Música", "Dança", "História", "Cultura", 
  "Arte", "Poesia", "Palavra", "Silêncio", "Vento", "Chuva", "Flor", 
  "Árvore", "Montanha", "Rio", "Estrela", "Lua", "Céu", "Terra", 
  "Fogo", "Água", "Ar", "Espaço", "Universo", "Alma", "Espírito", 
  "Mente", "Corpo", "Sentimento", "Emoção", "Pensamento", "Ideia", 
  "Criatividade", "Inovação", "Sucesso", "Vitória", "Desafio", 
  "Viagem", "Aventura", "Destino", "Futuro", "Passado", "Presente", 
  "Agora", "Sempre", "Nunca", "Talvez", "Quem", "Quando", "Onde", 
  "Porquê", "Verdade", "Mentira", "Segredo", "Mistério", "Magia", 
  "Milagre", "Fé", "Deus", "Anjo", "Demónio", "Herói", "Vilão",
  "História", "Memória", "Lembrança", "Esquecimento"
];



export type PortugueseNetworkProps = Record<string, any>;

const PortugueseNetwork: React.FC<PortugueseNetworkProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  wordColor = "#000000", // Changed default to black for white boxes
  lineColor = "#4a90e2",
  wordCount = 30,
  connectionRadius = 250,
  fontSize = 24,
  floatingSpeed = 1,
  floatingAmplitude = 10,
  durationInSeconds = 10,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 1. Generate Stable Nodes
  const nodes = useMemo(() => {
    return Array.from({ length: wordCount }).map((_, i) => {
      // Position Logic: Keep away from very edges (padding 10%)
      const paddingX = width * 0.1;
      const paddingY = height * 0.15; // Increased top padding slightly for Title
      const availableW = width - paddingX * 2;
      const availableH = height - paddingY * 2;

      return {
        id: i,
        text: WORD_BANK[i % WORD_BANK.length],
        baseX: paddingX + random(`x-${i}`) * availableW,
        baseY: paddingY + random(`y-${i}`) * availableH,
        // Unique phase for floating animation
        phase: random(`phase-${i}`) * Math.PI * 2,
        // Stagger entrance delay
        delay: i * 1, 
      };
    });
  }, [wordCount, width, height]);

  // 2. Calculate Current Positions (Animation Loop)
  const animatedNodes = nodes.map((node) => {
    // Floating Effect
    const floatY = Math.sin((frame / fps) * floatingSpeed + node.phase) * floatingAmplitude;
    const floatX = Math.cos((frame / fps) * floatingSpeed * 0.5 + node.phase) * (floatingAmplitude * 0.5);

    // Entrance Animation (Spring)
    const entrance = spring({
      frame: frame - node.delay,
      fps,
      config: { damping: 12, stiffness: 100 },
    });
    
    return {
      ...node,
      x: node.baseX + floatX,
      y: node.baseY + floatY,
      scale: entrance,
      opacity: interpolate(entrance, [0, 1], [0, 1], { extrapolateRight: "clamp" }),
    };
  });

  // 3. Calculate Connections
  const lines = useMemo(() => {
    const connections: React.ReactNode[] = [];
    
    for (let i = 0; i < animatedNodes.length; i++) {
      for (let j = i + 1; j < animatedNodes.length; j++) {
        const nodeA = animatedNodes[i];
        const nodeB = animatedNodes[j];

        const dx = nodeA.x - nodeB.x;
        const dy = nodeA.y - nodeB.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < connectionRadius) {
          // Opacity based on distance (closer = stronger)
          const distOpacity = interpolate(
            dist,
            [0, connectionRadius],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Opacity based on node appearance (wait for both to appear)
          const nodeOpacity = Math.min(nodeA.opacity, nodeB.opacity);
          
          if (nodeOpacity > 0.01) {
             connections.push(
              <line
                key={`line-${i}-${j}`}
                x1={nodeA.x}
                y1={nodeA.y}
                x2={nodeB.x}
                y2={nodeB.y}
                stroke={lineColor}
                strokeWidth={8} // Increased line thickness from 3 to 8
                strokeOpacity={distOpacity * nodeOpacity * 0.6}
                strokeLinecap="round"
                style={{ transition: "none" }}
              />
            );
          }
        }
      }
    }
    return connections;
  }, [animatedNodes, connectionRadius, lineColor]);


  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat" }}>
      
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: 50,
          width: "100%",
          textAlign: "center",
          fontSize: 64,
          fontWeight: 700,
          color: "#ffffff",
          zIndex: 10,
          textShadow: "0 4px 10px rgba(0,0,0,0.5)",
        }}
      >
        High Frequency Words
      </div>

      {/* Layer 1: Connections (SVG) */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
        }}
      >
        {lines}
      </svg>

      {/* Layer 2: Words */}
      {animatedNodes.map((node) => (
        <div
          key={node.id}
          style={{
            position: "absolute",
            left: node.x,
            top: node.y,
            transform: `translate(-50%, -50%) scale(${node.scale})`,
            opacity: node.opacity,
            color: wordColor,
            fontSize: fontSize,
            fontWeight: 600,
            textShadow: "none",
            whiteSpace: "nowrap",
            transition: "none",
            // Updated Box Styles: White background
            backgroundColor: "#ffffff", 
            padding: "8px 16px",
            borderRadius: "16px",
            border: `3px solid ${lineColor}`,
            boxShadow: "0 4px 15px rgba(0,0,0,0.3)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {node.text}
        </div>
      ))}
      
    </AbsoluteFill>
  );
};

export default PortugueseNetwork;